const test = require('node:test');
const assert = require('node:assert/strict');
const { cronMatches } = require('./cron');

const at = (iso) => new Date(iso);

test('every field a star matches any time', () => {
  assert.equal(cronMatches('* * * * *', at('2024-03-05T10:20:00Z')), true);
});

test('minute and hour', () => {
  assert.equal(cronMatches('30 9 * * *', at('2024-03-05T09:30:00Z')), true);
  assert.equal(cronMatches('30 9 * * *', at('2024-03-05T09:31:00Z')), false);
});

test('steps and lists', () => {
  assert.equal(cronMatches('*/15 * * * *', at('2024-03-05T10:45:00Z')), true);
  assert.equal(cronMatches('0 8,12,18 * * *', at('2024-03-05T12:00:00Z')), true);
});

test('day matching rule: neither starts with *', () => {
  // 13th or Friday
  // 2024-03-15 is Friday. 13th is Wednesday.
  // Expression: 0 0 13 * 5 (day 13 or Friday)
  assert.equal(cronMatches('0 0 13 * 5', at('2024-03-15T00:00:00Z')), true); // Friday
  assert.equal(cronMatches('0 0 13 * 5', at('2024-03-13T00:00:00Z')), true); // 13th
  assert.equal(cronMatches('0 0 13 * 5', at('2024-03-14T00:00:00Z')), false); // Thursday 14th
});

test('day matching rule: at least one starts with *', () => {
  // * * 13 * * -> dom=13, dow=*
  assert.equal(cronMatches('0 0 13 * *', at('2024-03-13T00:00:00Z')), true);
  assert.equal(cronMatches('0 0 13 * *', at('2024-03-15T00:00:00Z')), false);

  // * * * * 5 -> dom=*, dow=5 (Friday)
  assert.equal(cronMatches('0 0 * * 5', at('2024-03-15T00:00:00Z')), true);
  assert.equal(cronMatches('0 0 * * 5', at('2024-03-14T00:00:00Z')), false);
});

test('errors and edge cases', () => {
  // wrong field count
  assert.throws(() => cronMatches('* * * *', at('2024-03-05T10:20:00Z')), SyntaxError);
  assert.throws(() => cronMatches('* * * * * *', at('2024-03-05T10:20:00Z')), SyntaxError);

  // out of range values
  assert.throws(() => cronMatches('60 * * * *', at('2024-03-05T10:20:00Z')), SyntaxError);
  assert.throws(() => cronMatches('* 24 * * *', at('2024-03-05T10:20:00Z')), SyntaxError);
  assert.throws(() => cronMatches('* * 0 * *', at('2024-03-05T10:20:00Z')), SyntaxError);
  assert.throws(() => cronMatches('* * 32 * *', at('2024-03-05T10:20:00Z')), SyntaxError);
  assert.throws(() => cronMatches('* * * 0 *', at('2024-03-05T10:20:00Z')), SyntaxError);
  assert.throws(() => cronMatches('* * * 13 *', at('2024-03-05T10:20:00Z')), SyntaxError);
  assert.throws(() => cronMatches('* * * * 7', at('2024-03-05T10:20:00Z')), SyntaxError);

  // reversed range
  assert.throws(() => cronMatches('10-5 * * * *', at('2024-03-05T10:20:00Z')), SyntaxError);

  // step 0 or negative
  assert.throws(() => cronMatches('*/0 * * * *', at('2024-03-05T10:20:00Z')), SyntaxError);
  assert.throws(() => cronMatches('*/-1 * * * *', at('2024-03-05T10:20:00Z')), SyntaxError);

  // N/S with single number not allowed
  assert.throws(() => cronMatches('5/2 * * * *', at('2024-03-05T10:20:00Z')), SyntaxError);

  // Type errors
  assert.throws(() => cronMatches(123, at('2024-03-05T10:20:00Z')), TypeError);
  assert.throws(() => cronMatches('* * * * *', 'not a date'), TypeError);
  assert.throws(() => cronMatches('* * * * *', new Date('invalid')), TypeError);
});
